"use strict";(self.webpackChunkdronahq_docs=self.webpackChunkdronahq_docs||[]).push([[47510],{66029:e=>{e.exports=JSON.parse('{"pluginId":"agents","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docSidebar":[{"type":"category","label":"Getting Started","collapsible":false,"collapsed":false,"className":"sidebar_category_heading","items":[{"type":"link","label":"Introduction","href":"/agents/getting-started/introduction","docId":"getting-started/introduction"},{"type":"link","label":"Keywords","href":"/agents/getting-started/keywords","docId":"getting-started/keywords"},{"type":"link","label":"Semantic Query","href":"/agents/getting-started/semantic-query","docId":"getting-started/semantic-query"},{"type":"link","label":"Instruction","href":"/agents/getting-started/instruction","docId":"getting-started/instruction"},{"type":"link","label":"Tools Overview","href":"/agents/getting-started/tools-overview","docId":"getting-started/tools-overview"},{"type":"link","label":"Chat Interface","href":"/agents/getting-started/chat-interface","docId":"getting-started/chat-interface"},{"type":"link","label":"Credit Usage Guide","href":"/agents/getting-started/credit-usage","docId":"getting-started/credit-usage"}],"href":"/agents/category/getting-started"},{"type":"category","label":"Guardrails","collapsible":false,"collapsed":false,"className":"sidebar_category_heading","items":[{"type":"link","label":"Introduction","href":"/agents/guardrails/introduction","docId":"guardrails/introduction"},{"type":"link","label":"Output Policy","href":"/agents/guardrails/output-policy","docId":"guardrails/output-policy"},{"type":"link","label":"Prompt Policy","href":"/agents/guardrails/prompt-policy","docId":"guardrails/prompt-policy"}],"href":"/agents/category/guardrails"},{"type":"category","label":"Triggers","collapsible":false,"collapsed":false,"className":"sidebar_category_heading","items":[{"type":"link","label":"Introduction","href":"/agents/triggers/introduction","docId":"triggers/introduction"},{"type":"category","label":"Inbuilt Triggers","collapsible":true,"collapsed":true,"items":[{"type":"link","label":"Webhook","href":"/agents/triggers/inbuilt-triggers/webhook","docId":"triggers/inbuilt-triggers/webhook"},{"type":"link","label":"Scheduler","href":"/agents/triggers/inbuilt-triggers/scheduler","docId":"triggers/inbuilt-triggers/scheduler"},{"type":"link","label":"WhatsApp","href":"/agents/triggers/inbuilt-triggers/whatsapp","docId":"triggers/inbuilt-triggers/whatsapp"},{"type":"link","label":"Instagram","href":"/agents/triggers/inbuilt-triggers/instagram","docId":"triggers/inbuilt-triggers/instagram"},{"type":"link","label":"Facebook Messenger","href":"/agents/triggers/inbuilt-triggers/facebook","docId":"triggers/inbuilt-triggers/facebook"}],"href":"/agents/category/inbuilt-triggers"},{"type":"link","label":"DronaHQ Triggers","href":"/agents/triggers/dronahq-triggers","docId":"triggers/DronaHQ Triggers"}],"href":"/agents/category/triggers"},{"type":"category","label":"Widgets","collapsible":false,"collapsed":false,"className":"sidebar_category_heading","items":[{"type":"link","label":"Introduction","href":"/agents/widgets/introduction","docId":"widgets/introduction"},{"type":"link","label":"Creating Widgets","href":"/agents/widgets/creating widgets","docId":"widgets/creating widgets"},{"type":"link","label":"Available Plugins","href":"/agents/widgets/plugins","docId":"widgets/plugins"},{"type":"link","label":"Interactive Widgets","href":"/agents/widgets/interactive widgets","docId":"widgets/interactive widgets"}],"href":"/agents/category/widgets"}]},"docs":{"getting-started/chat-interface":{"id":"getting-started/chat-interface","title":"Chat Interface","description":"The AI Agent Chat Interface is the front-end component that allows end-users to interact with your configured AI Agent. This blueprint details the properties available for editing the interface to match your application\'s branding and user experience requirements.","sidebar":"docSidebar"},"getting-started/credit-usage":{"id":"getting-started/credit-usage","title":"Credit Usage Guide","description":"Overview","sidebar":"docSidebar"},"getting-started/instruction":{"id":"getting-started/instruction","title":"Instruction","description":"Overview","sidebar":"docSidebar"},"getting-started/introduction":{"id":"getting-started/introduction","title":"Introduction","description":"Welcome to DronaHQ Agents, a powerful platform for building AI-driven workflows, copilots, and agentic automations inside your apps\u2014without managing infrastructure. This guide will help you get started quickly by setting up your environment, creating your first agent, connecting tools, and deploying.","sidebar":"docSidebar"},"getting-started/keywords":{"id":"getting-started/keywords","title":"Keywords","description":"Keywords are predefined variables in a DronaHQ\u2019s agentic platform that users can use in their agent instruction. They provide important information about the logged-in user or the agent\'s state, which is vital for building logical workflows.","sidebar":"docSidebar"},"getting-started/semantic-query":{"id":"getting-started/semantic-query","title":"Semantic Query","description":"Overview","sidebar":"docSidebar"},"getting-started/tools-overview":{"id":"getting-started/tools-overview","title":"Tools Overview","description":"DronaHQ Tools ecosystem has 900+ powerful tools to help developers quickly build data-driven apps, integrate AI and databases, and automate workflows with ease.","sidebar":"docSidebar"},"guardrails/introduction":{"id":"guardrails/introduction","title":"Introduction","description":"A Guardrail Policy is a robust set of rules and constraints designed to govern the behavior of AI agents within the DronaHQ Agentic Platform. These policies act as a secure wrapper around your LLM interactions, ensuring that every prompt and response is safe, compliant, and aligned with your organization\u2019s operational standards.","sidebar":"docSidebar"},"guardrails/output-policy":{"id":"guardrails/output-policy","title":"Output Policy","description":"The Output Policy acts as a final validation layer, scanning the LLM\'s generated response before it reaches the end user. This ensures that the agent\'s output is safe, accurate, and professional, preventing hallucinations or data leaks that might have bypassed the initial prompt checks.","sidebar":"docSidebar"},"guardrails/prompt-policy":{"id":"guardrails/prompt-policy","title":"Prompt Policy","description":"Prompt Policies act as the first line of defense in your AI agent\'s execution flow. They intercept user messages to prevent security breaches, maintain data privacy, and ensure content safety.The Prompt Policy is divided into specialized scanners that can be individually Enabled or Disabled based on your security requirements.","sidebar":"docSidebar"},"triggers/DronaHQ Triggers":{"id":"triggers/DronaHQ Triggers","title":"DronaHQ Triggers","description":"DronaHQ supports 145+ triggers from major platforms and services. These triggers allow your agents to respond to events from various applications and services automatically.","sidebar":"docSidebar"},"triggers/inbuilt-triggers/facebook":{"id":"triggers/inbuilt-triggers/facebook","title":"Facebook Messenger","description":"The Facebook Messenger Trigger allows your AI agent to respond automatically when users send messages on Facebook Messenger.","sidebar":"docSidebar"},"triggers/inbuilt-triggers/instagram":{"id":"triggers/inbuilt-triggers/instagram","title":"Instagram","description":"The Instagram Trigger allows your AI agent to respond automatically when users send messages on Instagram Direct Messages.","sidebar":"docSidebar"},"triggers/inbuilt-triggers/scheduler":{"id":"triggers/inbuilt-triggers/scheduler","title":"Scheduler","description":"The Scheduler Trigger allows you to run your AI agent automatically at defined times or intervals\u2014without any user interaction.","sidebar":"docSidebar"},"triggers/inbuilt-triggers/webhook":{"id":"triggers/inbuilt-triggers/webhook","title":"Webhook","description":"The Webhook Trigger allows you to activate your AI agent when an HTTP request is received at a unique webhook URL. This enables your agent to respond to events from external systems, third-party services, or custom applications in real-time.","sidebar":"docSidebar"},"triggers/inbuilt-triggers/whatsapp":{"id":"triggers/inbuilt-triggers/whatsapp","title":"WhatsApp","description":"The WhatsApp Trigger allows your AI agent to respond automatically when users send messages on WhatsApp.","sidebar":"docSidebar"},"triggers/introduction":{"id":"triggers/introduction","title":"Introduction","description":"Agent Triggers define when and how an AI Agent starts running.","sidebar":"docSidebar"},"widgets/creating widgets":{"id":"widgets/creating widgets","title":"Creating Widgets","description":"Widgets can be created inside the Agent Builder in DronaHQ. These widgets allow developers to define custom UI components that render structured responses generated by AI agents.","sidebar":"docSidebar"},"widgets/interactive widgets":{"id":"widgets/interactive widgets","title":"Interactive Widgets","description":"Widgets in DronaHQ can be interactive, allowing users to trigger actions directly from the UI rendered by the agent. These interactions enable the widget to send responses back to the agent, which can then continue the conversation flow or perform additional actions.","sidebar":"docSidebar"},"widgets/introduction":{"id":"widgets/introduction","title":"Introduction","description":"Widgets in DronaHQ Agent Builder allow developers to create custom UI components that AI agents can use to","sidebar":"docSidebar"},"widgets/plugins":{"id":"widgets/plugins","title":"Available Plugins","description":"The following plugins are available inside widget components.","sidebar":"docSidebar"}}}')}}]);